45	// nexusGroupServer starts a Nexus that says "group" on the generic endpoint with
46	// no member listed there, so the format endpoint (path holding "/group/") decides.
47	func nexusGroupServer(t *testing.T, format http.HandlerFunc) config.RegistryItem {
48		t.Helper()
49		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
50			if !strings.Contains(r.URL.Path, "/group/") {
51				_, _ = w.Write([]byte(`{"type":"group","format":"docker","attributes":{"group":{"memberNames":[]}}}`))
52				return
53			}
54			format(w, r)
55		}))
56		t.Cleanup(srv.Close)
57		return config.RegistryItem{
58			Slug:     groupSlug,
59			Kind:     config.KindGroup,
60			Provider: config.ProviderNexus,
61			URL:      srv.URL + "/repository/docker-group",
62			AuthMode: config.AuthAnonymous,
63		}
64	}
